\begin{tikzpicture}[scale=0.6, font=\sffamily]
  % base plate
  \draw[very thick] (0,0) -- (8,0);

  % mercury dish
  \fill[black!30] (2,0) rectangle (6,1);
  \draw (2,1) -- (6,1);

  % bell jar, open at the base plate
  \draw[thick] (1,0) -- (1,7.2) -- (7,7.2) -- (7,0);

  % glass tube standing in the mercury, closed at the top
  \draw[thick] (3.5,1) -- (3.5,6.5) -- (4.5,6.5) -- (4.5,1);
  \fill[black!30] (3.5,1) rectangle (4.5,2.5);

  % height h of mercury above the dish surface
  \fill (4,2.5) circle (2pt);
  \draw[<->] (4,1) -- (4,2.5) node[midway, right] {$h$};

  % pipe to the air pump at B
  \draw[thick] (7,6.5) -- (8.6,6.5) node[above] {$B$};

  % caption
  \node[below] at (4,-0.8) {\textbf{Fig. 6.1}};
\end{tikzpicture}
